      "additionalProperties": false,
      "required": [
        "schema",
        "protocol",
        "actorId",
        "expiresAtMs"
      ],
      "properties": {
        "schema": {
          "const": "semio.hub.document-socket-grant/v1"
        },
        "protocol": {
          "const": "semio.session.v1"
        },
        "actorId": {
          "type": "string",
          "pattern": "^hub\\.v1\\.[0-9a-f]{64}$"
        },
        "expiresAtMs": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        }
      }
    },
